// Draws the logo centred on the screen, shifted up by offsetY. Plots per pixel so it follows orientation.
inline void drawBadrLabsLogo(const GfxRenderer& renderer, const bool invertedAfter = false, const int offsetY = -20) {
  const uint8_t* bitmap = invertedAfter ? BadrLabsLogoDark : BadrLabsLogo;
  constexpr int rowBytes = (BadrLabsLogoWidth + 7) / 8;
  const int left = (renderer.getScreenWidth() - BadrLabsLogoWidth) / 2;
  const int top = (renderer.getScreenHeight() - BadrLabsLogoHeight) / 2 + offsetY;
  for (int row = 0; row < BadrLabsLogoHeight; row++) {
    for (int col = 0; col < BadrLabsLogoWidth; col++) {
      if (((bitmap[row * rowBytes + (col >> 3)] >> (7 - (col & 7))) & 1) == 0) {
        renderer.drawPixel(left + col, top + row, true);
      }
    }
  }
}
